39	  /** Gallery card that matches the image currently loaded as the active file (for focus ring) */
40	  const [gallerySelectedFilename, setGallerySelectedFilename] = useState<string | null>(null);
41	  const promptInputRef = useRef<HTMLInputElement>(null);
42	
43	  const handleFile = useCallback((file: File) => {
44	    setGallerySelectedFilename(null);
