8	  onClose: () => void;
9	}
10	
11	type BrushSize = 'small' | 'medium' | 'large';
12	const BRUSH_SIZES: Record<BrushSize, number> = { small: 12, medium: 28, large: 52 };
13	
14	interface Stroke {
15	  points: Array<{ x: number; y: number }>;
16	  size: number;
17	}
